CREATE DATABASE IF NOT EXISTS `alkindo_db`;
USE `alkindo_db`;

CREATE TABLE IF NOT EXISTS `products` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `type_of_resin` varchar(255) DEFAULT NULL,
  `alkindo_name` varchar(255) DEFAULT NULL,
  `noarez_exp` varchar(255) DEFAULT NULL,
  `noarez_lokal` varchar(255) DEFAULT NULL,
  `solvent` varchar(255) DEFAULT NULL,
  `tg` varchar(50) DEFAULT NULL,
  `nv` varchar(50) DEFAULT NULL,
  `viscosity` varchar(50) DEFAULT NULL,
  `av_solution` varchar(50) DEFAULT NULL,
  `color_app` varchar(100) DEFAULT NULL,
  `performance_features` text DEFAULT NULL,
  `application` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
);

